"""PWA files for the phone app: manifest, service worker and icons (the icons are embedded, nothing to upload).
Needs HTTPS to be installable: Chrome > menu > Install app. Pages are loaded network-first, so every GitHub update shows up at once."""
import base64, json

MANIFEST = '{"name": "Screener", "short_name": "Screener", "description": "Crypto screener and AI", "start_url": "/app", "scope": "/", "display": "standalone", "orientation": "portrait", "background_color": "#0c0f24", "theme_color": "#0c0f24", "icons": [{"src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"}, {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"}, {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"}]}'
SW = "const C='screener-v1';\nself.addEventListener('install',e=>self.skipWaiting());\nself.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));\nself.addEventListener('fetch',e=>{\n  const u=new URL(e.request.url);\n  if(e.request.method!=='GET'||u.pathname.startsWith('/api/')||u.pathname==='/sw.js')return;\n  e.respondWith(fetch(e.request).then(r=>{const c=r.clone();caches.open(C).then(x=>x.put(e.request,c));return r}).catch(()=>caches.match(e.request)))\n});\n"
ICON_192 = base64.b64decode('')
ICON_512 = base64.b64decode('')


def asset(path):
    """-> (content_type, bytes, cache_header) for a PWA file, else None"""
    path = path.split("?")[0]
    if path == "/manifest.webmanifest":
        return "application/manifest+json", MANIFEST.encode(), "no-cache"
    if path == "/sw.js":
        return "application/javascript", SW.encode(), "no-cache"
    if path == "/icon-192.png":
        return "image/png", ICON_192, "public, max-age=86400"
    if path == "/icon-512.png":
        return "image/png", ICON_512, "public, max-age=86400"
    return None
